# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMA-000001",
    "name": "Muhammad محمد",
    "kind": "first-name",
    "meaning": "Muhammad (محمد) is a masculine given name in Arabic. Meaning: Praised. From the root h-m-d, 'to praise'; the most given "
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Muh")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

